{
  "duration_weeks": 12,
  "phases": [
    {
      "name": "Immediate Recovery - Protected Movement",
      "weeks": 2,
      "focus": "Re-establish gentle movement, breathing and pelvic floor activation while respecting surgical healing and OB restrictions."
    },
    {
      "name": "Foundational Movement & Core Re-education",
      "weeks": 4,
      "focus": "Progress mobility, walking conditioning and gentle core/pelvic floor re-education avoiding loaded abdominal work until clearance."
    },
    {
      "name": "Progressive Strength & Conditioning Intro",
      "weeks": 4,
      "focus": "Introduce safer resisted and standing functional strength patterns, increase walking conditioning and gradually prepare for heavier loading post-clearance."
    },
    {
      "name": "Consolidation & Return to Regular Training",
      "weeks": 2,
      "focus": "Consolidate gains, transition toward normalised core and strength work contingent on medical clearance for heavier lifting."
    }
  ],
  "weekly_template": {
    "days_per_week": 4,
    "day_types": [
      "Walk + Pelvic floor/breathing",
      "Gentle mobility & low-load strength (mat-based)",
      "Active recovery: walk + mobility",
      "Functional standing strength & conditioning (bodyweight/progressive)"
    ]
  },
  "non_negotiables": [
    "OB cleared for light activity only — walking, no abs, no heavy lifting until the six-week check",
    "No abdominal exercises (no 'abs') until cleared at six-week check",
    "No heavy lifting until cleared at six-week check",
    "Train only at home with available equipment: yoga mat (no additional equipment required)"
  ]
}
